@import url('https://fonts.googleapis.com/css2?family=Qwitcher+Grypen:wght@400;700&family=Outfit:wght@300;400;500;600;700;800;900&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --background: hsl(0, 0%, 3%);
  --foreground: hsl(0, 0%, 98%);
  --muted: hsl(0, 15%, 8%);
  --muted-foreground: hsl(0, 5%, 45%);
  --popover: hsl(0, 15%, 5%);
  --popover-foreground: hsl(0, 0%, 98%);
  --card: hsl(0, 20%, 6%);
  --card-foreground: hsl(0, 0%, 98%);
  --border: hsl(0, 15%, 15%);
  --input: hsl(0, 15%, 12%);
  --primary: hsl(0, 75%, 45%);
  --primary-foreground: hsl(0, 0%, 98%);
  --secondary: hsl(0, 20%, 8%);
  --secondary-foreground: hsl(0, 0%, 98%);
  --accent: hsl(0, 60%, 20%);
  --accent-foreground: hsl(0, 0%, 98%);
  --destructive: hsl(0, 84.2%, 60.2%);
  --destructive-foreground: hsl(60, 9.1%, 97.8%);
  --ring: hsl(0, 75%, 45%);
  --radius: 0.75rem;

  /* Custom luxury color palette */
  --deep-black: hsl(0, 0%, 3%);
  --charcoal: hsl(0, 5%, 8%);
  --dark-red: hsl(0, 60%, 12%);
  --crimson: hsl(0, 75%, 35%);
  --blood-red: hsl(0, 85%, 45%);
  --luxury-gold: hsl(45, 95%, 60%);
  --pearl-white: hsl(0, 0%, 98%);
  --smoke-gray: hsl(0, 0%, 65%);
  --shadow-red: hsl(0, 40%, 8%);

  /* Gradient definitions */
  --gradient-primary: linear-gradient(135deg, var(--deep-black) 0%, var(--dark-red) 50%, var(--shadow-red) 100%);
  --gradient-accent: linear-gradient(45deg, var(--crimson) 0%, var(--blood-red) 100%);
  --gradient-overlay: linear-gradient(180deg, transparent 0%, var(--deep-black) 100%);

  /* Glass morphism variables */
  --glass-bg: rgba(255, 255, 255, 0.03);
  --glass-bg-hover: rgba(255, 255, 255, 0.05);
  --glass-border: rgba(255, 255, 255, 0.1);
  --glass-border-hover: rgba(220, 38, 38, 0.3);
  --glass-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
  --glass-shadow-hover: 0 16px 64px rgba(220, 38, 38, 0.1);
}

.dark {
  --background: hsl(0, 0%, 4%);
  --foreground: hsl(0, 0%, 98%);
  --muted: hsl(0, 0%, 10%);
  --muted-foreground: hsl(0, 0%, 40%);
  --popover: hsl(0, 0%, 4%);
  --popover-foreground: hsl(0, 0%, 98%);
  --card: hsl(0, 0%, 10%);
  --card-foreground: hsl(0, 0%, 98%);
  --border: hsl(0, 0%, 20%);
  --input: hsl(0, 0%, 20%);
  --primary: hsl(43, 74%, 49%);
  --primary-foreground: hsl(0, 0%, 0%);
  --secondary: hsl(0, 0%, 10%);
  --secondary-foreground: hsl(0, 0%, 98%);
  --accent: hsl(0, 0%, 10%);
  --accent-foreground: hsl(0, 0%, 98%);
  --destructive: hsl(0, 62.8%, 30.6%);
  --destructive-foreground: hsl(0, 0%, 98%);
  --ring: hsl(43, 74%, 49%);
}

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
    background-color: var(--dark-bg);
    color: var(--foreground);
  }
}

@layer components {
  .brand-font {
    font-family: 'Qwitcher Grypen', cursive;
    font-weight: 700;
    letter-spacing: 0.02em;
  }

  /* Main heading font styles using Outfit */
  h1, h2 {
    font-family: 'Outfit', sans-serif;
    font-weight: 700;
    letter-spacing: -0.025em;
  }

  .heading-font {
    font-family: 'Outfit', sans-serif;
    font-weight: 700;
    letter-spacing: -0.025em;
  }

  .nav-link {
    @apply transition-all duration-300 font-medium hover:text-primary relative;
    text-shadow: 0 0 8px rgba(255, 255, 255, 0.1);
  }

  .nav-link::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background: var(--gradient-accent);
    transition: width 0.3s ease;
  }

  .nav-link:hover::after {
    width: 100%;
  }

  .hero-gradient {
    background: var(--gradient-primary);
    position: relative;
  }

  .hero-gradient::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(circle at center, transparent 20%, var(--deep-black) 100%);
    z-index: 1;
  }

  .luxury-accent {
    color: var(--luxury-gold);
    text-shadow: 0 0 20px rgba(255, 215, 0, 0.3);
  }

  .crimson-accent {
    color: var(--crimson);
    text-shadow: 0 0 15px rgba(220, 38, 38, 0.4);
  }

  .crimson-accent-hover:hover {
    color: var(--blood-red);
    text-shadow: 0 0 25px rgba(220, 38, 38, 0.6);
    transition: all 0.3s ease;
  }

  .text-smoke {
    color: var(--smoke-gray);
  }

  /* Glass Morphism Utilities */
  .glass {
    background: var(--glass-bg);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
    border: 1px solid var(--glass-border);
    box-shadow: var(--glass-shadow);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Only apply hover effects on devices that support true hover */
  @media (hover: hover) {
    .glass:hover {
      background: var(--glass-bg-hover);
      border-color: var(--glass-border-hover);
      box-shadow: var(--glass-shadow-hover);
      transform: translateY(-2px);
    }
  }

  .glass-card {
    background: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.1);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  }

  /* Only apply hover effects on devices that support true hover */
  @media (hover: hover) {
    .glass-card:hover {
      background: rgba(0, 0, 0, 0.3);
      border-color: rgba(220, 38, 38, 0.2);
      box-shadow: 0 16px 64px rgba(0, 0, 0, 0.5), 0 0 40px rgba(220, 38, 38, 0.1), inset 0 1px 0 rgba(255, 255, 255, 0.15);
      transform: translateY(-4px) scale(1.02);
    }
  }

  /* Mobile-friendly static version */
  .glass-card-static {
    background: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255, 255, 255, 0.08);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  }

  .glass-button {
    background: rgba(220, 38, 38, 0.1);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(220, 38, 38, 0.2);
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
    transition: all 0.3s ease;
  }

  /* Only apply hover effects on devices that support true hover */
  @media (hover: hover) {
    .glass-button:hover {
      background: rgba(220, 38, 38, 0.2);
      border-color: rgba(220, 38, 38, 0.4);
      box-shadow: 0 8px 32px rgba(220, 38, 38, 0.2);
      transform: translateY(-1px);
    }
  }

  .bg-deep-black {
    background-color: var(--deep-black);
  }

  .bg-charcoal {
    background-color: var(--charcoal);
  }

  .bg-dark-red {
    background-color: var(--dark-red);
  }

  .bg-gradient-primary {
    background: var(--gradient-primary);
  }

  .bg-gradient-accent {
    background: var(--gradient-accent);
  }

  .border-crimson {
    border-color: var(--crimson);
  }

  .btn-primary {
    @apply bg-primary text-primary-foreground font-bold px-10 py-4 rounded-full transition-all duration-300 transform hover:scale-105 shadow-lg;
    background: var(--gradient-accent);
    box-shadow: 0 8px 32px rgba(220, 38, 38, 0.3);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .btn-primary:hover {
    box-shadow: 0 12px 40px rgba(220, 38, 38, 0.5);
    transform: translateY(-2px) scale(1.05);
  }

  .btn-secondary {
    @apply font-bold px-10 py-4 rounded-full transition-all duration-300 transform hover:scale-105;
    background: transparent;
    border: 2px solid var(--luxury-gold);
    color: var(--luxury-gold);
    text-transform: uppercase;
    letter-spacing: 1px;
    box-shadow: 0 0 20px rgba(255, 215, 0, 0.2);
  }

  .btn-secondary:hover {
    background: var(--luxury-gold);
    color: var(--deep-black);
    box-shadow: 0 0 30px rgba(255, 215, 0, 0.5);
    transform: translateY(-2px) scale(1.05);
  }

  .btn-outline {
    @apply font-bold px-10 py-4 rounded-full transition-all duration-300 transform hover:scale-105;
    background: transparent;
    border: 2px solid var(--smoke-gray);
    color: var(--smoke-gray);
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  .btn-outline:hover {
    border-color: var(--luxury-gold);
    color: var(--luxury-gold);
    box-shadow: 0 0 20px rgba(255, 215, 0, 0.3);
    transform: translateY(-2px) scale(1.05);
  }

  .luxury-card {
    @apply rounded-2xl shadow-2xl transition-all duration-500;
    background: linear-gradient(145deg, var(--charcoal) 0%, var(--dark-red) 100%);
    border: 1px solid var(--crimson);
    backdrop-filter: blur(10px);
  }

  .luxury-card:hover {
    transform: translateY(-8px);
    box-shadow: 0 25px 50px rgba(220, 38, 38, 0.2);
  }

  .glass-effect {
    backdrop-filter: blur(20px);
    background: rgba(0, 0, 0, 0.8);
    border: 1px solid rgba(220, 38, 38, 0.2);
  }

  .animate-float {
    animation: float 6s ease-in-out infinite;
  }

  .animate-glow {
    animation: glow 2s ease-in-out infinite alternate;
  }

  .animate-slide-up {
    animation: slideUp 0.8s ease-out forwards;
  }

  .animate-fade-in {
    animation: fadeIn 1s ease-out forwards;
  }
}

@keyframes float {
  0%, 100% { transform: translateY(0px); }
  50% { transform: translateY(-10px); }
}

@keyframes glow {
  0% { text-shadow: 0 0 20px rgba(255, 215, 0, 0.3); }
  100% { text-shadow: 0 0 30px rgba(255, 215, 0, 0.8), 0 0 40px rgba(255, 215, 0, 0.4); }
}

@keyframes slideUp {
  0% { opacity: 0; transform: translateY(30px); }
  100% { opacity: 1; transform: translateY(0); }
}

@keyframes fadeIn {
  0% { opacity: 0; }
  100% { opacity: 1; }
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--deep-black);
}

::-webkit-scrollbar-thumb {
  background: var(--gradient-accent);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--blood-red);
}

